SINA_SMART["cellbio1-cycle-nucleus"] = {"lecture":"cellbio1-cycle-nucleus","title":"The cell cycle and the nucleus","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"cellbio1-cycle-nucleus:e0","text":"Cycle: G1, S, G2, M (+ cytokinesis); G0 for non-dividing cells (neurons, lens).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cycle-nucleus:e1","text":"Checkpoints: G1/S (restriction point), G2/M (DNA complete), metaphase (spindle).","topic":"Checkpoints and regulators","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cycle-nucleus:e2","text":"Failure → apoptosis; if the cycle cannot stop → cancer.","topic":"Checkpoints and regulators","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cycle-nucleus:e3","text":"p53 and pRb: tumour suppressors at checkpoints 1-2.","topic":"Checkpoints and regulators","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cycle-nucleus:e4","text":"Cyclin/CDK drive E2F, SPF, MPF; activators CDC25, CAK; inhibitors p16, p21, p27, Wee1.","topic":"Checkpoints and regulators","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cycle-nucleus:e5","text":"Envelope: two membranes, 30 nm space, outer continuous with RER, inner with lamina.","topic":"The interphase nucleus","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cycle-nucleus:e6","text":"Progeria: lamin A mutation.","topic":"The interphase nucleus","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cycle-nucleus:e7","text":"Nucleolus: rDNA loops on chromosomes 13, 14, 15, 21, 22.","topic":"The interphase nucleus","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cycle-nucleus:e8","text":"Barr body = inactive X (XX: 1; XXX: 2).","topic":"The interphase nucleus","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cycle-nucleus:e9","text":"Pores: 2,000-4,000; import via NLS + importin α/β + RanGTP; export via NES + exportin-1.","topic":"Nuclear pores and transport","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"gfzmkq":"a","q6u1l1":"a","gcgskb":"a","1hlal13":"a","1ta4r5q":"a","17qyyfe":"a","1yiq3g2":"a","1hs4fl9":"a","xy1ww8":"a","14paprm":"a","w549fz":"a","1qd4oil":"a","1l517xt":"a","1pgklbr":"a","it8ygh":"x","nhpwai":"x"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":2},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"cellbio1-cycle-nucleus:e0":{"s":0,"u":["Cycle: G1, S, G2, M (+ cytokinesis); G0 for non-dividing cells (neurons, lens).","Some cells stop dividing and stay in G0 (neurons, lens cells).","The cell cycle alternates interphase ( G1, S, G2 ) and mitosis (prophase, prometaphase, metaphase, anaphase, telophase) with cytokinesis ."],"dp":[]},"cellbio1-cycle-nucleus:e1":{"s":1,"u":["Checkpoints: G1/S (restriction point), G2/M (DNA complete), metaphase (spindle).","Three major checkpoints : (1) G1/S (start, restriction point, point of no return): is the environment favourable and the cell large enough (nucleo-cytoplasmic ratio)?","(3) metaphase : are all chromosomes aligned on the equatorial plate and attached to the spindle?"],"dp":[]},"cellbio1-cycle-nucleus:e2":{"s":1,"u":["Failure → apoptosis; if the cycle cannot stop → cancer.","If anything is wrong, the cycle stops and apoptosis begins; if it cannot stop, cancer may result. p53 and pRb control checkpoints 1 and 2: they are tumour suppressors (anti-oncogenes)."],"dp":[]},"cellbio1-cycle-nucleus:e3":{"s":1,"u":["p53 and pRb: tumour suppressors at checkpoints 1-2.","If anything is wrong, the cycle stops and apoptosis begins; if it cannot stop, cancer may result. p53 and pRb control checkpoints 1 and 2: they are tumour suppressors (anti-oncogenes)."],"dp":[{"h":"Why checkpoint failure leads to cancer","t":"Checkpoints stop a cell that has damaged DNA or misattached chromosomes, giving it time to repair or pushing it into apoptosis. When p53 or pRb is lost, damaged cells keep dividing, passing on and accumulating mutations. That is why these genes are called tumour suppressors and are mutated in many cancers. Source: the lecture's checkpoint slides."}]},"cellbio1-cycle-nucleus:e4":{"s":1,"u":["Cyclin/CDK drive E2F, SPF, MPF; activators CDC25, CAK; inhibitors p16, p21, p27, Wee1.","Factors E2F , SPF (start-promoting) and MPF (mitosis-promoting) are driven by cyclin/CDK kinases , whose levels oscillate through the cycle; activators CDC25 (A, B, C) , Polo kinase, CAK; inhibitors p16, p21, p27, Wee1 ."],"dp":[]},"cellbio1-cycle-nucleus:e5":{"s":2,"u":["Envelope: two membranes, 30 nm space, outer continuous with RER, inner with lamina.","Nuclear envelope : two membranes separated by a ~ 30 nm perinuclear space ; the outer membrane bears ribosomes and is continuous with the rough ER ; the inner membrane is lined by the nuclear lamina (lamins A, B, C, intermediate filaments) attached by lamina-associated proteins."],"dp":[]},"cellbio1-cycle-nucleus:e6":{"s":2,"u":["Progeria: lamin A mutation.","Progeria is due to lamin A mutation: chromosomes attach poorly to the lamina, deforming the nucleus."],"dp":[]},"cellbio1-cycle-nucleus:e7":{"s":2,"u":["Nucleolus: rDNA loops on chromosomes 13, 14, 15, 21, 22.","Nucleolus : ribosome factory built on ~10 rDNA loops from chromosomes 13, 14, 15, 21, 22 ; central fibrillar region (rDNA, rRNA) and peripheral granular region (pre-ribosomes)."],"dp":[{"h":"Why the nucleolus sits on five chromosomes","t":"Cells need huge numbers of ribosomes, so the genes for ribosomal RNA are repeated many times on the short arms of the acrocentric chromosomes 13, 14, 15, 21 and 22. These loops cluster together in interphase to form the nucleolus, which is why these same chromosomes are involved in Robertsonian translocations. Source: the lecture's nucleolus slide and the genetics course."}]},"cellbio1-cycle-nucleus:e8":{"s":2,"u":["Barr body = inactive X (XX: 1; XXX: 2).","Also granules for mRNA maturation and splicing, Cajal bodies (telomerase repairing TTAGGG telomeres ), and the Barr body : the condensed inactive X in females (XX: 1 Barr body; XXX: 2)."],"dp":[]},"cellbio1-cycle-nucleus:e9":{"s":3,"u":["Pores: 2,000-4,000; import via NLS + importin α/β + RanGTP; export via NES + exportin-1.","2,000-4,000 pores per nucleus (fewer in S phase, more in G1/G2).","Import needs a nuclear localisation signal (NLS) : importin α binds the NLS, importin β binds importin α, the complex docks on Nup358, crosses via elastic FxFG repeats, reaches Nup153, and RanGTP dissociates it inside (e.g. import of pRb); importins are recycled."],"dp":[]}},"meta":{"gfzmkq":{"a":"recall","vg":"cellbio1-cycle-nucleus:e0/recall/1"},"q6u1l1":{"a":"recall","vg":"cellbio1-cycle-nucleus:e1/recall/1"},"gcgskb":{"a":"recall","vg":"cellbio1-cycle-nucleus:e1/recall/2"},"1hlal13":{"a":"recall","vg":"cellbio1-cycle-nucleus:e1/recall/2"},"1ta4r5q":{"a":"recall","vg":"cellbio1-cycle-nucleus:e3/recall/1"},"17qyyfe":{"a":"recall","vg":"cellbio1-cycle-nucleus:e4/recall/1"},"1yiq3g2":{"a":"recall","vg":"cellbio1-cycle-nucleus:e5/recall/1"},"1hs4fl9":{"a":"recall","vg":"cellbio1-cycle-nucleus:e5/recall/2"},"xy1ww8":{"a":"relationship","vg":"cellbio1-cycle-nucleus:e6/relationship/1"},"14paprm":{"a":"recall","vg":"cellbio1-cycle-nucleus:e7/recall/1"},"w549fz":{"a":"recall","vg":"cellbio1-cycle-nucleus:e8/recall/1"},"1qd4oil":{"a":"recall","vg":"cellbio1-cycle-nucleus:e8/recall/2"},"1l517xt":{"a":"recall","vg":"cellbio1-cycle-nucleus:e9/recall/1"},"1pgklbr":{"a":"recall","vg":"cellbio1-cycle-nucleus:e9/recall/1"}},"explRev":"e910c2afba77"};
